<template><WorkspacePage title="调度日志" subtitle="查询任务执行记录和异常详情"><a-form v-show="showSearch" class="query-form" layout="inline"><a-form-item label="任务名称"><a-input v-model:value="queryParams.jobName" allow-clear /></a-form-item><a-form-item label="任务组名"><a-select v-model:value="queryParams.jobGroup" allow-clear :options="groupOptions" /></a-form-item><a-form-item label="执行状态"><a-select v-model:value="queryParams.status" allow-clear :options="statusOptions" /></a-form-item><a-form-item label="执行时间"><a-range-picker v-model:value="dateRange" value-format="YYYY-MM-DD" /></a-form-item><a-form-item><a-button type="primary" @click="handleQuery"><SearchOutlined />搜索</a-button><a-button @click="resetQuery"><ReloadOutlined />重置</a-button></a-form-item></a-form><div class="toolbar"><a-space><a-button danger :disabled="!ids.length" @click="handleDelete" v-hasPermi="['monitor:job:remove']"><DeleteOutlined />删除</a-button><a-button danger @click="handleClean" v-hasPermi="['monitor:job:remove']"><ClearOutlined />清空</a-button><a-button @click="handleExport" v-hasPermi="['monitor:job:export']"><DownloadOutlined />导出</a-button><a-button @click="handleClose"><CloseOutlined />关闭</a-button></a-space><a-button shape="circle" @click="showSearch=!showSearch"><FilterOutlined /></a-button></div><ResourceTable :columns="columns" :rows="jobLogList" :loading="loading" :pagination="false" row-key="jobLogId" :scroll="{x:1000}"><template #headerCell="{column}"><a-checkbox v-if="column.key==='select'" :checked="allSelected" :indeterminate="ids.length>0&&!allSelected" @change="toggleAll" /></template><template #bodyCell="{column,record}"><template v-if="column.key==='select'"><a-checkbox :checked="ids.includes(record.jobLogId)" @change="e=>toggleRow(record,e.target.checked)" /></template><template v-else-if="column.key==='jobGroup'"><dict-tag :options="sys_job_group" :value="record.jobGroup" /></template><template v-else-if="column.key==='status'"><dict-tag :options="sys_common_status" :value="record.status" /></template><template v-else-if="column.key==='createTime'">{{parseTime(record.createTime)}}</template><template v-else-if="column.key==='action'"><a-button type="link" @click="handleView(record)" v-hasPermi="['monitor:job:query']"><EyeOutlined />详细</a-button></template></template></ResourceTable><a-pagination v-if="total>0" v-model:current="queryParams.pageNum" v-model:page-size="queryParams.pageSize" :total="total" show-size-changer @change="getList"/><JobDetail v-model:visible="open" :row="form" type="log"/></WorkspacePage></template>
<script setup name="JobLog">
import{ClearOutlined,CloseOutlined,DeleteOutlined,DownloadOutlined,EyeOutlined,FilterOutlined,ReloadOutlined,SearchOutlined}from'@ant-design/icons-vue';import WorkspacePage from '@/components/Antd/WorkspacePage.vue';import ResourceTable from '@/components/Antd/ResourceTable.vue';import feedback from '@/plugins/antdFeedback';import JobDetail from './detail.vue';import{getJob}from'@/api/monitor/job';import{listJobLog,delJobLog,cleanJobLog}from'@/api/monitor/jobLog'
const{proxy}=getCurrentInstance();const{sys_common_status,sys_job_group}=proxy.useDict('sys_common_status','sys_job_group');const route=useRoute();const jobLogList=ref([]),open=ref(false),loading=ref(true),showSearch=ref(true),ids=ref([]),total=ref(0),dateRange=ref([]),form=ref({});const queryParams=reactive({pageNum:1,pageSize:10,jobName:undefined,jobGroup:undefined,status:undefined});const groupOptions=computed(()=>sys_job_group.value.map(x=>({label:x.label,value:x.value}))),statusOptions=computed(()=>sys_common_status.value.map(x=>({label:x.label,value:x.value})));const allSelected=computed(()=>jobLogList.value.length>0&&jobLogList.value.every(x=>ids.value.includes(x.jobLogId)));const columns=[{title:'',key:'select',width:48},{title:'日志编号',dataIndex:'jobLogId',key:'jobLogId',width:90},{title:'任务名称',dataIndex:'jobName',key:'jobName',ellipsis:true},{title:'任务组名',key:'jobGroup'},{title:'调用目标字符串',dataIndex:'invokeTarget',key:'invokeTarget',ellipsis:true},{title:'日志信息',dataIndex:'jobMessage',key:'jobMessage',ellipsis:true},{title:'执行状态',key:'status'},{title:'执行时间',key:'createTime',width:180},{title:'操作',key:'action',width:90}]
async function getList(){loading.value=true;try{const r=await listJobLog(proxy.addDateRange({...queryParams},dateRange.value));jobLogList.value=r.rows;total.value=r.total;ids.value=[]}finally{loading.value=false}}function handleClose(){proxy.$tab.closeOpenPage({path:'/monitor/job'})}function handleQuery(){queryParams.pageNum=1;getList()}function resetQuery(){dateRange.value=[];Object.assign(queryParams,{pageNum:1,jobName:undefined,jobGroup:undefined,status:undefined});handleQuery()}function toggleRow(row,on){ids.value=on?[...new Set([...ids.value,row.jobLogId])]:ids.value.filter(x=>x!==row.jobLogId)}function toggleAll(e){ids.value=e.target.checked?jobLogList.value.map(x=>x.jobLogId):[]}function handleView(row){form.value=row;open.value=true}async function handleDelete(){try{await feedback.confirm(`是否确认删除调度日志编号为"${ids.value}"的数据项?`);await delJobLog(ids.value);feedback.msgSuccess('删除成功');getList()}catch{}}async function handleClean(){try{await feedback.confirm('是否确认清空所有调度日志数据项?');await cleanJobLog();feedback.msgSuccess('清空成功');getList()}catch{}}function handleExport(){proxy.download('monitor/jobLog/export',{...queryParams},`job_log_${Date.now()}.xlsx`)};(async()=>{const id=route.params?.jobId;if(id!==undefined&&id!=0){const r=await getJob(id);queryParams.jobName=r.data.jobName;queryParams.jobGroup=r.data.jobGroup}getList()})()
</script><style scoped>.query-form{padding:16px;margin-bottom:12px;border:1px solid var(--workspace-border)}.toolbar{display:flex;justify-content:space-between;margin-bottom:12px}:deep(.ant-pagination){justify-content:flex-end;margin-top:14px}</style>
